import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: Marker — a status or divider row inside a conversation.
 *
 *   variant="inline"     the default marker row
 *   variant="border"     keeps marker alignment but separates the next row
 *   variant="separator"  a labelled divider, e.g. a date or section break
 *
 * Recipes:
 *   - Status:  set role="status" and include a <Spinner /> so in-progress
 *              updates are announced.
 *   - Shimmer: add the `shimmer` utility class to MarkerContent for the
 *              streaming-text effect (ships with the shadcn package).
 *   - asChild on Marker turns it into a link or button.
 */
const markerVariants = cva(
  "flex items-center gap-2 text-xs font-medium text-muted-foreground [&_svg:not([class*='size-'])]:size-3.5",
  {
    variants: {
      variant: {
        inline: "w-fit",
        border: "w-full border-b pb-2",
        separator:
          "w-full before:h-px before:flex-1 before:bg-border after:h-px after:flex-1 after:bg-border",
      },
    },
    defaultVariants: { variant: "inline" },
  }
);

function Marker({
  className,
  variant,
  asChild = false,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof markerVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "div";
  return (
    <Comp
      data-slot="marker"
      data-variant={variant}
      className={cn(markerVariants({ variant }), className)}
      {...props}
    />
  );
}

/** The marker's text. Add the `shimmer` class for streaming content. */
function MarkerContent({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="marker-content" className={cn("min-w-0", className)} {...props} />;
}

/** An icon beside the content. Use `flex-col` on Marker to stack it above. */
function MarkerIcon({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="marker-icon"
      className={cn("flex shrink-0 items-center justify-center [&_svg]:pointer-events-none", className)}
      {...props}
    />
  );
}

export { Marker, MarkerContent, MarkerIcon, markerVariants };
